import itertools

def is_close(p1, p2):
    for a, b in zip(p1, p2):
        if abs(a - b) > 1:
            return False
    return True

def solve(n):
    perms = list(itertools.permutations(range(1, n + 1)))
    adj = {i: [] for i in range(len(perms))}
    for i in range(len(perms)):
        for j in range(i + 1, len(perms)):
            if is_close(perms[i], perms[j]):
                adj[i].append(j)
                adj[j].append(i)

    # Find max independent set. 
    # Since we need the size of the max independent set, we can use a simple recursive approach with memoization.
    memo = {}
    def max_independent_set(nodes):
        nodes = tuple(sorted(nodes))
        if not nodes:
            return 0
        if nodes in memo:
            return memo[nodes]

        v = nodes[0]
        # Either v is in the independent set
        res1 = 1 + max_independent_set([n for n in nodes[1:] if n not in adj[v]])
        # Or v is not in the independent set
        res2 = max_independent_set(list(nodes[1:]))

        res = max(res1, res2)
        memo[nodes] = res
        return res

    # The graph might be disconnected, so find max independent set for each component and sum them.
    visited = [False] * len(perms)
    total_max_independent_set = 0
    for i in range(len(perms)):
        if not visited[i]:
            component = []
            stack = [i]
            visited[i] = True
            while stack:
                u = stack.pop()
                component.append(u)
                for v in adj[u]:
                    if not visited[v]:
                        visited[v] = True
                        stack.append(v)

            # For this component, find the max independent set.
            memo = {}
            # We need to pass only the nodes in the component to max_independent_set
            # Wait, the current max_independent_set function is fine if we pass only the component's nodes.
            total_max_independent_set += max_independent_set(component)

    return total_max_independent_set

for n in range(2, 5):
    print(f"n={n}, max_independent_set={solve(n)}")

