def solve_n5():
    perms = list(itertools.permutations(range(1, 6)))
    adj = {i: [] for i in range(len(perms))}
    for i in range(len(perms)):
        for j in range(i + 1, len(perms)):
            if is_close(perms[i], perms[j]):
                adj[i].append(j)
                adj[j].append(i)

    # Check if the graph is a union of disjoint cliques
    components = []
    visited = [False] * len(perms)
    for i in range(len(perms)):
        if not visited[i]:
            comp = []
            stack = [i]
            visited[i] = True
            while stack:
                u = stack.pop()
                comp.append(u)
                for v in adj[u]:
                    if not visited[v]:
                        visited[v] = True
                        stack.append(v)
            components.append(comp)

    for i, comp in enumerate(components):
        print(f"Component {i} size: {len(comp)}")
        # Check if it's a clique
        is_clique = True
        for u in comp:
            if len(adj[u]) != len(comp) - 1:
                is_clique = False
                break
        print(f"Component {i} is clique: {is_clique}")

